# -*- coding: utf-8 -*-
"""Authored finite work log; time averages and completion cohorts stay distinct."""
from html import escape as e

SOURCES=[
 dict(id='kanban',title='Kanban Guides · The Kanban Guide, May2025',url='https://kanbanguides.org/the-kanban-guide/2025.5/',edition='2025.5',page_updated='2025-05-01',checked='2026-10-27',kind='특정 방법론의 최소 지침',note='2025.5판의 Definition of Workflow·Active Management·Flow Metrics를2026-10-27 원문 확인. 시작·종료 경계, WIP·처리량·작업 나이·사이클 타임과 막힌 작업 관리의 참고. 지침의 고유 정의를 모든 조직의 용어·PMP 공식 목차와 동일시하지 않음. 아래 작업 기록·수치·그림·판단 연습은 독립 창작.'),
 dict(id='little-original',title='Little · A Proof for the Queuing Formula: L = λW',url='https://pubsonline.informs.org/doi/abs/10.1287/opre.9.3.383',published='1961-06-01',checked='2026-10-27',kind='원 연구 · 출판사 초록과 서지 확인',note='Little, Operations Research9(3),383–387,1961. 출판사 초록의 평균 관계와 유한 평균·정상성 등 제시 조건을 확인. 논문 본문 증명 전체를 읽었다는 뜻은 아님. 아래 유한 작업 기록의 면적 계산은 자체 산술 검증이며 장기 평균 정리의 증명·실제 예측 모형을 대신하지 않음.')]
DATA={'horizon':10,'cutoff':6,'unit':'연속 일','items':[{'id':'A','start':0,'finish':4},{'id':'B','start':1,'finish':5,'blocked':[2,4]},{'id':'C','start':4,'finish':8},{'id':'D','start':7,'finish':9}],'full':{'area':14,'averageWIP':1.4,'completed':4,'throughput':0.4,'averageCycle':3.5},'partial':{'area':10,'averageWIP':'5/3','completed':2,'throughput':'1/3','averageCompletedCycle':4,'ageC':2,'snapshotWIP':1}}

def render():
 out='<section class="flow-study"><span class="eyebrow">MEASURE THE SAME FLOW</span><h2>평균을 나누기 전에,<br>어디부터 어디까지 셌나요?</h2><div class="notice"><b>가상 기록 · 연속 시간의 0~10일</b><p>시작은 팀이 작업을 당겨 착수한 순간, 완료는 합의한 검증·전달 조건을 충족한 순간입니다. 취소·재개·분할·범위 변경은 없고 시작 전·10일 종료 때 남아 있는 작업도 없습니다. 휴일·영업일 환산은 하지 않습니다. 이4건의 사후 기록으로 계산하며 실제 회사·Jira 자료가 아닙니다.</p></div><h3>먼저 측정 경계를 고정해요</h3><ol class="flow-boundary"><li><b>요청 접수</b><span>착수 전 대기는 아래 WIP 밖</span></li><li><b>착수 → 진행·대기·검증</b><span>이 사례의 WIP·사이클 타임 경계</span></li><li><b>완료</b><span>완료 수와 사이클 타임 확정</span></li></ol><p>여기서 사이클 타임은 착수부터 완료까지의 경과 시간입니다. 예를 들어 별도 요청이0일에 들어와2일에 착수하고7일에 완료되면, 접수→완료는7일, 착수→완료는5일입니다. 조직에서 리드타임 등 다른 이름을 쓰더라도 경계를 함께 적습니다. 착수 후 막힌 시간도 경과 시간에 포함되며, 실제 손을 움직인 작업 시간만을 뜻하지 않습니다.</p><h3>같은 10일 축에 놓은 작업 기록</h3><p class="small muted">초록 막대: 착수~완료의 체류 구간 · 줄무늬: B의2~4일 승인 응답 대기 · 흰 점선:6일 시점. 사후에 완성한 기록이며6일 당시에는 C의 최종 완료일을 아직 모릅니다.</p><div class="flow-timeline"><div class="flow-time-axis" aria-hidden="true">'+''.join('<span style="left:'+str(x*10)+'%">'+str(x)+'</span>' for x in [0,2,4,6,8,10])+'</div>'
 for item in DATA['items']:
  start,finish=item['start'],item['finish']
  desc=f"{item['id']}: {start}일 착수, {finish}일 완료, 사이클 타임{finish-start}일"+(' ·2~4일 대기도 포함' if item.get('blocked') else '')
  out+='<section class="flow-item" data-flow-item="'+item['id']+'"><h4>'+e(desc)+'</h4><div class="flow-rail" role="img" aria-label="'+e(desc)+'"><span class="flow-stay" style="left:'+str(start*10)+'%;width:'+str((finish-start)*10)+'%"></span>'
  if item.get('blocked'):out+='<span class="flow-blocked" style="left:20%;width:20%"></span>'
  out+='<i class="flow-cutoff"></i></div></section>'
 out+='</div><div class="concept-scroll flow-ledger-scroll"><table class="flow-ledger"><caption>전체 기록의 확정값 · 단위: 일</caption><thead><tr><th scope="col">작업</th><th scope="col">착수</th><th scope="col">완료</th><th scope="col">사이클 타임</th></tr></thead><tbody>'+''.join('<tr><th scope="row">'+i['id']+'</th><td>'+str(i['start'])+'</td><td>'+str(i['finish'])+'</td><td>'+str(i['finish']-i['start'])+'</td></tr>' for i in DATA['items'])+'</tbody></table></div><h3>10일 전체를 보면 평균 관계가 맞아요</h3><div class="flow-calculation"><p><b>체류 면적</b> = 4+4+4+2 = 14건·일</p><p><b>기간 평균 WIP</b> = 14건·일 / 10일 = 1.4건</p><p><b>완료 처리율</b> = 4건 / 10일 = 0.4건/일</p><p><b>완료 작업 평균 사이클 타임</b> = 14건·일 / 4건 = 3.5일</p><p class="flow-identity">0.4건/일 × 3.5일 = 1.4건</p></div><p>체류 면적은 각 시점의 진행 중 작업 수를 시간에 걸쳐 합산한 값입니다. 각 작업의 착수~완료 막대 면적을 더해도 같습니다. 이 예제는 관찰 시작 전 유입과 끝의 미완료가 없어, 전체 체류 면적이 완료한4건의 총 사이클 타임과 일치합니다. 평균 WIP1.4는 보드에 카드1.4장이 있다는 뜻이 아닙니다.</p><h3>6일까지만 자르면, 완료한 작업만으로는 부족해요</h3><div class="flow-window-grid"><section><h4>0~6일 동안 머문 면적</h4><p>A4 + B4 + C2 = 10건·일</p><p>기간 평균 WIP = 10/6 = 5/3건<br>약1.667건</p><p>C는6일에도 미완료여서, 관찰 창 안의2일만 면적에 들어갑니다.</p></section><section><h4>6일까지 완료한 A·B만 계산</h4><p>처리율 = 2/6 = 1/3건/일<br>완료 작업 평균 사이클 타임 = 4일</p><p>둘의 곱 = 4/3건, 약1.333건<br>기간 평균 WIP5/3건과 다릅니다.</p><p>미완료 C의 창 안 체류 면적2건·일이 완료 작업의 평균에는 빠졌기 때문입니다.</p></section></div><aside class="concept-trap"><b>법칙이 틀렸다고 결론 내리지 않기</b><p>임의의 짧은 창에서 구한 WIP 시간 평균과 그 창에서 완료한 작업만의 평균 체류시간을 무조건 결합하면 경계 효과가 생깁니다. 위 전체10일의 일치는 이 유한 기록의 면적 항등식입니다. 실제 흐름의 장기 평균·유입과 유출·체류 분포가 같은 조건으로 유지된다는 증거는 아닙니다.</p></aside><h3>“지금 진행 중”과 “기간 평균”도 달라요</h3><p>6일의 순간 WIP는 C 한 건입니다. 이를0~6일 처리율1/3건/일로 나눈3일을 그 기간의 평균 사이클 타임이라고 부르면 서로 다른 측정값을 섞은 것입니다. 같은 순간 C의 작업 나이는6−4=2일입니다. 나이는 미완료 작업의 지금까지 경과 시간이며, C가 총2일 만에 완료됐다는 뜻도 “평균3.5일이니1.5일 남았다”는 뜻도 아닙니다.</p><h3>숫자를 보고 어떤 행동을 할까요?</h3><ol class="decision-steps"><li>시작·완료·관찰 구간·작업 단위와 취소·재개 처리를 먼저 맞춥니다. 완료 기준을 낮춰 처리량을 올리지 않습니다.</li><li>완료 작업의 시간 분포와 함께 진행 중 작업의 나이·막힘을 살핍니다. B의 승인 대기 원인을 확인하고 담당·응답 경로·해결 시점을 협의합니다.</li><li>예를 들어 착수 전에 승인 자료를 확인하는 정책을 실험할 수 있습니다. 대기가 단순히 경계 밖으로 옮겨지지 않았는지 접수→완료 시간도 보고 품질·완료 흐름을 함께 확인합니다.</li><li>WIP를 줄이면 처리율도 그대로일 것이라고 가정하지 않습니다. 협업·용량·작업 구성·외부 의존성이 함께 바뀔 수 있으므로 개선 가설과 결과를 비교합니다.</li></ol><h3>기록을 가리고 판단해 보기</h3><p class="small muted">비채점 적용 연습 · 원래의 WIP10건·처리율2건/일 채점 문제와 별도입니다.</p>'
 for q,a in [
 ('B가2일 동안 막혔으니 사이클 타임을2일로 줄여 기록할까요?','이 사례의 경계는 착수1일→완료5일이므로 사이클 타임4일입니다. 승인 대기2일은 그 안에 포함됩니다. 별도의 실제 작업 시간이나 대기 시간을 분석할 수 있지만, 경과 시간에서 몰래 대기를 빼서 다른 정의로 바꾸지 않습니다.'),
 ('6일 시점의 C 나이2일을 완료 사이클 타임 표에 넣을까요?','C는 미완료라 최종 사이클 타임은 아직 모릅니다. 나이2일로 따로 살피고 현재 막힘·다음 행동을 확인합니다. 완료 코호트에 넣으면 미완료 작업을 짧게 끝난 작업처럼 왜곡합니다.'),
 ('전체 평균 WIP1.4를 WIP 제한1로 설정하라는 뜻으로 읽을까요?','아닙니다. 시간 평균1.4와 시작을 제어하는 정책상의 정수 한도는 다릅니다. 현재 기록은 순간 WIP가2인 구간도 있습니다. 용량·협업·품질·외부 대기를 고려해 정책을 정하고 변화를 관찰합니다.'),
 ('WIP10/처리율2=5일이면 새 작업의 완료를5일로 약속할까요?','아닙니다. 원래 채점 문제는 같은 경계의 안정적 평균이라는 가정 아래 평균 관계를 계산합니다. 개별 작업의 잔여 기간·백분위·달력 완료일을 보장하지 않습니다. 실제 자료의 분포·작업 특성과 변화도 확인해야 합니다.')]:
  out+='<details class="think-box flow-reflection"><summary>'+e(q)+'</summary><p>'+e(a)+'</p></details>'
 out+='<nav class="evidence-links" aria-label="흐름과 연결된 수업"><a class="text-link" href="pmp-lesson:n33">흐름과 팀 →</a><a class="text-link" href="pmp-lesson:n67">기술 품질과 재작업 →</a><a class="text-link" href="pmp-lesson:n69">지표와 사업 성과 →</a></nav><details class="evidence-source-details"><summary>출처·판본·적용 범위</summary><ul class="source-list">'
 for s in SOURCES:out+='<li><a href="'+e(s['url'])+'" target="_blank" rel="noopener">'+e(s['title'])+'</a><p>'+e(s['note'])+'</p></li>'
 return out+'</ul><p class="small muted">설명·작업 기록·그래프·경계 비교·연습은 자체 제작입니다. Little 원 논문의 전체 증명을 인용하거나 실제 처리율·완료일을 예측한 자료가 아닙니다.</p></details></section>'
